"use client";
import { useEffect, useState } from "react";

import cookies from "js-cookie";
import axios from "axios";


export default function EncadrantProfile({ user_id }) {
  const [encadrant, setEncadrant] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchEncadrantData = async () => {
      try {
        const token = cookies.get("token");
        if (!token) {
          throw new Error("Non autorisé. Veuillez vous connecter.");
        }

        const response = await axios.get(`http://localhost:5000/api/Encadrants/${user_id}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        setEncadrant(response.data);
      } catch (err) {
        setError(err.response?.data?.message || "Erreur lors de la récupération des données");
      } finally {
        setLoading(false);
      }
    };

    fetchEncadrantData();
  }, [user_id]);

  if (loading) {
    return <div className="text-center mt-10">Chargement en cours...</div>;
  }

  if (error) {
    return <div className="text-center text-red-500 mt-10">{error}</div>;
  }

  if (!encadrant) {
    return <div className="text-center mt-10">Aucune donnée disponible</div>;
  }

  return (
    <div className="p-6 bg-gray-100 min-h-screen">
      <h1 className="text-3xl font-bold text-center mb-8">Profil de l'Encadrant</h1>
      <div className="max-w-4xl mx-auto">
        <div className="bg-white p-6 rounded-lg shadow-md mb-8">
          <h2 className="text-2xl font-semibold mb-4">{encadrant.nom} {encadrant.prenom}</h2>
          <p className="text-gray-700">Email: {encadrant.email}</p>
          <p className="text-gray-700">Année: {encadrant.annee}</p>
        </div>

        <h2 className="text-2xl font-semibold mb-4">Sujets et Groupes</h2>
        {encadrant.sujets.map((sujet) => (
          <div key={sujet.idSujet} className="mb-8">
            <h3 className="text-xl font-bold mb-4">Sujet: {sujet.titre}</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {sujet.groupes.map((groupe) => (
                <div key={groupe.idGroupe} className="bg-white p-6 rounded-lg shadow-md">
                  <h4 className="text-lg font-semibold mb-2">Groupe: {groupe.nomGroupe}</h4>
                  <p className="text-gray-700 mb-2">
                    Tuteur: {groupe.tuteur.nom} {groupe.tuteur.prenom}
                  </p>
                  <div className="mb-4">
                    <h5 className="font-semibold">Étudiants:</h5>
                    <ul className="list-disc list-inside">
                      {groupe.etudiants.map((etudiant, index) => (
                        <li key={index}>{etudiant.nom} {etudiant.prenom}</li>
                      ))}
                    </ul>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}